import assert from "node:assert/strict";
import { describe, it } from "vite-plus/test";
import { escapeHtml, evalReportHtml } from "./report.ts";
import { formatTrialTotals, type CaseResult, type RunSummary } from "./result.ts";

const checksOk = {
  failures: [] as { check: string; message: string }[],
  lints: [] as string[],
  words: 0,
  dirtyWorktree: false,
  why: "present" as const,
  parts: 1,
  groups: 1,
  size: "small" as const,
  togetherOk: 0,
  togetherTotal: 0,
  apartOk: 0,
  apartTotal: 0,
};

function caseResult(over: Partial<CaseResult> & Pick<CaseResult, "id">): CaseResult {
  return {
    ok: true,
    durationMs: 12_000,
    tokens: 800,
    checks: checksOk,
    ...over,
  };
}

describe("eval HTML report", () => {
  it("escapes LLM text and links the produced review", () => {
    const summary: RunSummary = {
      stamp: "2026-09-13T03-13-34-249Z",
      skillTree: "963f6069f91e1b36d3fc5afb6f3beaac6f525d25",
      producerModel: "muse-spark-1.3-contributor",
      graderModel: "muse-spark-1.3-contributor",
      graders: true,
      cases: [
        caseResult({
          id: "comprehende-50",
          ok: false,
          producerError: undefined,
          validateError: undefined,
          checks: {
            ...checksOk,
            failures: [{ check: "why", message: "expected why absent, got present" }],
            why: "present",
          },
          document: { title: "Export vs serve", size: "small", why: "Invented <why>." },
          rubric: {
            run: {
              text: "",
              status: "finished",
              durationMs: 1,
              tokens: 1,
              steps: 1,
              toolCalls: [],
            },
            output: {
              must: [{ item: "states the copy", yes: true, quote: "copies <b>args</b>" }],
              good: [],
              mustNot: [{ item: "three-index slice", yes: true, quote: "caps with [:len:len]" }],
              bullets: [
                {
                  where: "group g1",
                  bullet: "Directory grouped. <script>alert(1)</script>",
                  holds: false,
                  note: "no such directory",
                },
              ],
            },
          },
          site: "/tmp/site",
          producer: {
            text: "ok",
            status: "finished",
            durationMs: 1,
            tokens: 1,
            steps: 1,
            toolCalls: [],
          },
        }),
        caseResult({ id: "comprehende-57" }),
      ],
    };
    const html = evalReportHtml(summary);
    assert.match(html, /1 of 2 cases failed deterministic checks/);
    assert.match(html, /producer muse-spark-1\.3-contributor/);
    assert.match(html, /grader muse-spark-1\.3-contributor/);
    assert.match(html, /skill 963f606/);
    assert.match(html, /expected why absent, got present/);
    assert.match(html, /\.\/comprehende-50\/site\/index.html/);
    assert.match(html, /\.\/comprehende-50\/producer.md/);
    assert.equal(html.includes("<script>alert(1)</script>"), false);
    assert.match(html, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    assert.match(html, /Invented &lt;why&gt;\./);
    assert.match(html, /Must 1 of 1/);
    assert.match(html, /copies &lt;b&gt;args&lt;\/b&gt;/);
    assert.match(html, /Must not 1 of 1/);
    assert.match(html, /lookFor and attention 0 of 1 true/);
    assert.match(html, /no such directory/);
    assert.doesNotMatch(html, /<h3>Good/);
    assert.doesNotMatch(html, /comprehende-57\/site/);
  });

  it("reports prose lint without failing the case", () => {
    const html = evalReportHtml({
      stamp: "2026-09-21T02-00-00-000Z",
      skillTree: "963f6069f91e1b36d3fc5afb6f3beaac6f525d25",
      producerModel: "muse-spark-1.3-contributor",
      graderModel: "muse-spark-1.3-contributor",
      graders: true,
      cases: [
        caseResult({
          id: "comprehende-67",
          checks: {
            ...checksOk,
            lints: ["document lookFor has a 28-word sentence"],
          },
        }),
      ],
    });
    assert.match(html, /All 1 case passed deterministic checks/);
    assert.match(html, />ok<\/span> comprehende-67/);
    assert.match(html, /document lookFor has a 28-word sentence/);
    assert.doesNotMatch(html, /class="case fail"/);
  });

  it("labels a smoke run with graders off", () => {
    const html = evalReportHtml({
      stamp: "2026-09-20T21-00-00-000Z",
      skillTree: "963f6069f91e1b36d3fc5afb6f3beaac6f525d25",
      producerModel: "muse-spark-1.3-contributor",
      graderModel: "muse-spark-1.3-contributor",
      graders: false,
      cases: [caseResult({ id: "comprehende-50" })],
    });
    assert.match(html, /graders off/);
    assert.doesNotMatch(html, /grader muse-spark/);
  });

  it("escapes HTML characters", () => {
    assert.equal(
      escapeHtml(`<a href="x">'&</a>`),
      "&lt;a href=&quot;x&quot;&gt;&#39;&amp;&lt;/a&gt;",
    );
  });
});

describe("repeated runs", () => {
  const failing = { ...checksOk, failures: [{ check: "size", message: "got small" }] };
  const trials = [
    caseResult({ id: "comprehende-57", trial: 1, site: "x" }),
    caseResult({ id: "comprehende-57", trial: 2, checks: failing }),
    caseResult({ id: "comprehende-57", trial: 3 }),
    caseResult({ id: "comprehende-50", trial: 1 }),
  ];

  it("counts passes per case and names the failed trials", () => {
    assert.deepEqual(formatTrialTotals(trials), [
      "comprehende-57  pass 2/3  failed t2",
      "comprehende-50  pass 1/1",
    ]);
  });

  it("links each trial to its own folder", () => {
    const html = evalReportHtml({
      stamp: "s",
      skillTree: "963f6069f91e1b36d3fc5afb6f3beaac6f525d25",
      producerModel: "m",
      graderModel: "m",
      graders: false,
      cases: trials,
    });
    assert.match(html, /href="\.\/comprehende-57\.t1\/site\/index\.html"/);
    assert.match(html, /id="comprehende-57\.t2"/);
  });
});
